"""Validated, serialisable simulation configuration for TUD-LBM.
:class:`SimulationConfig` is a **frozen** Python dataclass used for parsing, validation, and serialisation. It never enters a JIT boundary.
Usage::
from config.simulation_config import SimulationConfig
cfg = SimulationConfig( grid_shape=(128, 128), tau=0.8, nt=5000, collision_scheme="bgk", ) """
from __future__ import annotations import dataclasses from dataclasses import dataclass from dataclasses import field from typing import Any from typing import Literal from config.dir_config import BASE_RESULTS_DIR
CONFIG_SECTION: str = "config_section" ARRAY_ELIGIBLE: str = "array_eligible" NESTED_SWEEPABLE: str = "nested_sweepable"
def array_field( *, default=dataclasses.MISSING, default_factory=dataclasses.MISSING, section: str | None = None, nested_sweepable: bool = False, **kwargs, )-> field(): """Field factory for array-eligible SimulationConfig fields.
Args: section: Config section name for serialisation routing. nested_sweepable: If ``True``, sub-keys inside this dict field will also be inspected for list values during Cartesian-product expansion (e.g. ``gravity_force``, ``wetting_config``). """ metadata = dict(kwargs.pop("metadata", {})) metadata[ARRAY_ELIGIBLE] = True if nested_sweepable: metadata[NESTED_SWEEPABLE] = True if section is not None: metadata[CONFIG_SECTION] = section return field(default=default, default_factory=default_factory, metadata=metadata, **kwargs)
def _normalize_sequence(value): return tuple(value) if not isinstance(value, tuple) else value
def _first_if_list(value): if isinstance(value, list): return value[0] if value else value return value
def _validate_positive(value, name: str) -> None: if value is not None and value <= 0: msg = f"{name} must be positive, got {value}" raise ValueError(msg)
def _validate_nonnegative(value, name: str) -> None: if value is not None and value < 0: msg = f"{name} must be non-negative, got {value}" raise ValueError(msg)
def _valid_collision_schemes() -> set[str]: import operators.collision # noqa: F401 from registry import get_operator_names
return get_operator_names("collision_models")
def _valid_eos() -> set[str]: import operators.macroscopic # noqa: F401 from registry import get_operator_names
return get_operator_names("macroscopic") - {"standard"}
def _valid_lattices() -> set[str]: import setup.lattice # noqa: F401 from registry import get_operator_names
return get_operator_names("lattice")
@dataclass(frozen=True) class SimulationConfig: # ── Simulation identity ────────────────────────────────────── sim_type: Literal["single_phase", "multiphase"] = field( default="single_phase", metadata={CONFIG_SECTION: "identity"}, ) simulation_name: str | None = None
# ── Lattice & grid ─────────────────────────────────────────── lattice_type: str = "D2Q9" grid_shape: tuple[int, ...] = array_field(default=(64, 64))
# ── Time stepping ──────────────────────────────────────────── nt: int = array_field(default=1000) tau: float = array_field(default=1.0)
# ── Collision ──────────────────────────────────────────────── collision_scheme: str = array_field(default="bgk") k_diag: tuple[float, ...] | None = array_field(default=None)
# ── Boundary conditions (ONLY topology: which BC on which face) ── bc_config: dict[str, Any] | None = field( default=None, metadata={CONFIG_SECTION: "boundary_conditions"}, )
# ── Wetting model (promoted to first-class section) ────────── wetting_config: dict[str, Any] | None = array_field(default=None, section="wetting", nested_sweepable=True)
# ── Hysteresis model (promoted to first-class section) ─────── hysteresis_config: dict[str, Any] | None = array_field(default=None, section="hysteresis", nested_sweepable=True)
# ── Forces (each force is its own field, named by physics) ─── gravity_force: dict[str, Any] | None = array_field(default=None, section="gravity_force", nested_sweepable=True) electric_force: dict[str, Any] | None = array_field(default=None, section="electric_force", nested_sweepable=True) # ── Initialisation ─────────────────────────────────────────── init_type: str = "standard" init_dir: str | None = None initialisation: dict[str, Any] = field( default_factory=dict, metadata={CONFIG_SECTION: "initialisation"}, )
# ── Output / IO ────────────────────────────────────────────── results_dir: str = field(default=BASE_RESULTS_DIR, metadata={CONFIG_SECTION: "output"}) save_interval: int = 0 skip_interval: int = 0 save_fields: list[str] | None = field(default=None, metadata={CONFIG_SECTION: "output"}) plot_fields: list[str] | None = field(default=None, metadata={CONFIG_SECTION: "output"}) output_format: str | list[str] | None = field(default="numpy", metadata={CONFIG_SECTION: "output"}) output_dir: str | None = field(default=None, metadata={CONFIG_SECTION: "output"})
# ── Multiphase ─────────────────────────────────────────────── eos: str | None = array_field(default=None, section="multiphase") kappa: float | None = array_field(default=None, section="multiphase") rho_l: float | None = array_field(default=None, section="multiphase") rho_v: float | None = array_field(default=None, section="multiphase") interface_width: int | None = array_field(default=None, section="multiphase") g: float | None = array_field(default=None, section="multiphase")
# ── Extra / extensible ─────────────────────────────────────── extra: dict[str, Any] = field(default_factory=dict, metadata={CONFIG_SECTION: "extra"})
# Validation
def __post_init__(self) -> None: self._normalize() self._apply_defaults() self._validate_common() if self.sim_type == "multiphase": self._validate_multiphase()
def _normalize(self) -> None: object.__setattr__(self, "grid_shape", _normalize_sequence(self.grid_shape)) object.__setattr__(self, "output_format", _first_if_list(self.output_format)) if isinstance(self.output_format, str): object.__setattr__(self, "output_format", self.output_format.lower())
def _apply_defaults(self) -> None: if self.save_interval == 0: object.__setattr__(self, "save_interval", self.nt // 10) if self.bc_config is None: object.__setattr__( self, "bc_config", { "top": "periodic", "bottom": "periodic", "left": "periodic", "right": "periodic", }, )
def _validate_common(self) -> None: if len(self.grid_shape) < 2: msg = f"grid_shape must have at least 2 dimensions, got {len(self.grid_shape)}" raise ValueError(msg) if any(d <= 0 for d in self.grid_shape): msg = f"All grid dimensions must be positive, got {self.grid_shape}" raise ValueError(msg)
if self.lattice_type not in _valid_lattices(): valid = _valid_lattices() msg = f"lattice_type must be one of {valid}, got '{self.lattice_type}'" raise ValueError(msg)
if self.tau <= 0.5: msg = f"tau must be > 0.5 for stability, got {self.tau}" raise ValueError(msg)
if self.nt <= 0: msg = f"nt must be positive, got {self.nt}" raise ValueError(msg)
valid_schemes = _valid_collision_schemes() if self.collision_scheme not in valid_schemes: msg = f"collision_scheme must be one of {sorted(valid_schemes)}, got '{self.collision_scheme}'" raise ValueError(msg)
if self.collision_scheme == "mrt" and self.k_diag is None: msg = "k_diag must be provided when using MRT collision scheme" raise ValueError(msg)
_validate_nonnegative(self.save_interval, "save_interval") _validate_nonnegative(self.skip_interval, "skip_interval")
if self.init_type == "init_from_file" and self.init_dir is None: msg = "init_dir must be provided when init_type is 'init_from_file'" raise ValueError(msg)
if self.save_fields is not None: valid_fields = {"f", "rho", "u", "force", "force_ext", "h"} invalid = set(self.save_fields) - valid_fields if invalid: msg = f"Invalid save_fields: {invalid}. Valid fields: {valid_fields}" raise ValueError(msg)
def _validate_multiphase(self) -> None: required = ("kappa", "rho_l", "rho_v", "interface_width", "eos") for name in required: if getattr(self, name) is None: msg = f"'{name}' is required for multiphase simulations" raise ValueError(msg)
_validate_positive(self.rho_l, "rho_l") _validate_positive(self.rho_v, "rho_v") if self.rho_l is not None and self.rho_v is not None and self.rho_l <= self.rho_v: msg = f"rho_l ({self.rho_l}) must be greater than rho_v ({self.rho_v})" raise ValueError(msg) _validate_positive(self.kappa, "kappa") _validate_positive(self.interface_width, "interface_width")
valid_eos = _valid_eos() if self.eos not in valid_eos: msg = f"eos must be one of {sorted(valid_eos)}, got '{self.eos}'" raise ValueError(msg)
@property def is_single_phase(self) -> bool: return self.sim_type == "single_phase"
@property def is_multiphase(self) -> bool: return self.sim_type == "multiphase"
@property def force_enabled(self) -> bool: """True if any ``*_force`` field is populated.""" return any(getattr(self, f.name) is not None for f in dataclasses.fields(self) if f.name.endswith("_force"))
# Serialisation
def to_dict(self) -> dict[str, Any]: from dataclasses import asdict
d = asdict(self) extra = d.pop("extra", {}) d.update(extra) d["simulation_type"] = self.sim_type return d
def __repr__(self) -> str: return ( f"SimulationConfig(\n" f" sim_type={self.sim_type!r},\n" f" grid_shape={self.grid_shape!r},\n" f" lattice_type={self.lattice_type!r},\n" f" tau={self.tau!r},\n" f" nt={self.nt!r},\n" f" collision_scheme={self.collision_scheme!r},\n" f" init_type={self.init_type!r},\n" f")" )
def get_array_eligible_fields() -> frozenset[str]: return frozenset(f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(ARRAY_ELIGIBLE, False))
def get_nested_sweepable_fields() -> frozenset[str]: """Return field names whose dict sub-keys may carry list sweep values.""" return frozenset(f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(NESTED_SWEEPABLE, False))
def get_fields_for_section(section: str) -> frozenset[str]: return frozenset( f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(CONFIG_SECTION, "simulation_type") == section )

"""Validated, serialisable simulation configuration for TUD-LBM.
:class:`SimulationConfig` is a **frozen** Python dataclass used for parsing, validation, and serialisation. It never enters a JIT boundary.
Usage::
from config.simulation_config import SimulationConfig
cfg = SimulationConfig( grid_shape=(128, 128), tau=0.8, nt=5000, collision_scheme="bgk", ) """
from __future__ import annotations import dataclasses from dataclasses import dataclass from dataclasses import field from typing import Any from typing import Literal from config.dir_config import BASE_RESULTS_DIR
CONFIG_SECTION: str = "config_section" ARRAY_ELIGIBLE: str = "array_eligible" NESTED_SWEEPABLE: str = "nested_sweepable"
def array_field( *, default: Any = dataclasses.MISSING, default_factory: Any = dataclasses.MISSING, section: str | None = None, nested_sweepable: bool = False, **kwargs: Any, ) -> field: """Field factory for array-eligible SimulationConfig fields.
Args: default: Default value for the field. default_factory: Default factory function for the field. section: Config section name for serialisation routing. nested_sweepable: If ``True``, sub-keys inside this dict field will also be inspected for list values during Cartesian-product expansion (e.g. ``gravity_force``, ``wetting_config``). **kwargs: Additional keyword arguments passed to the field factory.
Returns: A dataclass field with array-eligible metadata. """ metadata = dict(kwargs.pop("metadata", {})) metadata[ARRAY_ELIGIBLE] = True if nested_sweepable: metadata[NESTED_SWEEPABLE] = True if section is not None: metadata[CONFIG_SECTION] = section return field(default=default, default_factory=default_factory, metadata=metadata, **kwargs)
def _normalize_sequence(value): return tuple(value) if not isinstance(value, tuple) else value
def _first_if_list(value): if isinstance(value, list): return value[0] if value else value return value
def _validate_positive(value, name: str) -> None: if value is not None and value <= 0: msg = f"{name} must be positive, got {value}" raise ValueError(msg)
def _validate_nonnegative(value, name: str) -> None: if value is not None and value < 0: msg = f"{name} must be non-negative, got {value}" raise ValueError(msg)
def _valid_collision_schemes() -> set[str]: import operators.collision # noqa: F401 from registry import get_operator_names
return get_operator_names("collision_models")
def _valid_eos() -> set[str]: import operators.macroscopic # noqa: F401 from registry import get_operator_names
return get_operator_names("macroscopic") - {"standard"}
def _valid_lattices() -> set[str]: import setup.lattice # noqa: F401 from registry import get_operator_names
return get_operator_names("lattice")
@dataclass(frozen=True) class SimulationConfig: # ── Simulation identity ────────────────────────────────────── sim_type: Literal["single_phase", "multiphase"] = field( default="single_phase", metadata={CONFIG_SECTION: "identity"}, ) simulation_name: str | None = None
# ── Lattice & grid ─────────────────────────────────────────── lattice_type: str = "D2Q9" grid_shape: tuple[int, ...] = array_field(default=(64, 64))
# ── Time stepping ──────────────────────────────────────────── nt: int = array_field(default=1000) tau: float = array_field(default=1.0)
# ── Collision ──────────────────────────────────────────────── collision_scheme: str = array_field(default="bgk") k_diag: tuple[float, ...] | None = array_field(default=None)
# ── Boundary conditions (ONLY topology: which BC on which face) ── bc_config: dict[str, Any] | None = field( default=None, metadata={CONFIG_SECTION: "boundary_conditions"}, )
# ── Wetting model (promoted to first-class section) ────────── wetting_config: dict[str, Any] | None = array_field(default=None, section="wetting", nested_sweepable=True)
# ── Hysteresis model (promoted to first-class section) ─────── hysteresis_config: dict[str, Any] | None = array_field(default=None, section="hysteresis", nested_sweepable=True)
# ── Forces (each force is its own field, named by physics) ─── gravity_force: dict[str, Any] | None = array_field(default=None, section="gravity_force", nested_sweepable=True) electric_force: dict[str, Any] | None = array_field(default=None, section="electric_force", nested_sweepable=True) # ── Initialisation ─────────────────────────────────────────── init_type: str = "standard" init_dir: str | None = None initialisation: dict[str, Any] = field( default_factory=dict, metadata={CONFIG_SECTION: "initialisation"}, )
# ── Output / IO ────────────────────────────────────────────── results_dir: str = field(default=BASE_RESULTS_DIR, metadata={CONFIG_SECTION: "output"}) save_interval: int = 0 skip_interval: int = 0 save_fields: list[str] | None = field(default=None, metadata={CONFIG_SECTION: "output"}) plot_fields: list[str] | None = field(default=None, metadata={CONFIG_SECTION: "output"}) output_format: str | list[str] | None = field(default="numpy", metadata={CONFIG_SECTION: "output"}) output_dir: str | None = field(default=None, metadata={CONFIG_SECTION: "output"})
# ── Multiphase ─────────────────────────────────────────────── eos: str | None = array_field(default=None, section="multiphase") kappa: float | None = array_field(default=None, section="multiphase") rho_l: float | None = array_field(default=None, section="multiphase") rho_v: float | None = array_field(default=None, section="multiphase") interface_width: int | None = array_field(default=None, section="multiphase") g: float | None = array_field(default=None, section="multiphase")
# ── Extra / extensible ─────────────────────────────────────── extra: dict[str, Any] = field(default_factory=dict, metadata={CONFIG_SECTION: "extra"})
# Validation
def __post_init__(self) -> None: self._normalize() self._apply_defaults() self._validate_common() if self.sim_type == "multiphase": self._validate_multiphase()
def _normalize(self) -> None: object.__setattr__(self, "grid_shape", _normalize_sequence(self.grid_shape)) object.__setattr__(self, "output_format", _first_if_list(self.output_format)) if isinstance(self.output_format, str): object.__setattr__(self, "output_format", self.output_format.lower())
def _apply_defaults(self) -> None: if self.save_interval == 0: object.__setattr__(self, "save_interval", self.nt // 10) if self.bc_config is None: object.__setattr__( self, "bc_config", { "top": "periodic", "bottom": "periodic", "left": "periodic", "right": "periodic", }, )
def _validate_common(self) -> None: if len(self.grid_shape) < 2: msg = f"grid_shape must have at least 2 dimensions, got {len(self.grid_shape)}" raise ValueError(msg) if any(d <= 0 for d in self.grid_shape): msg = f"All grid dimensions must be positive, got {self.grid_shape}" raise ValueError(msg)
if self.lattice_type not in _valid_lattices(): valid = _valid_lattices() msg = f"lattice_type must be one of {valid}, got '{self.lattice_type}'" raise ValueError(msg)
if self.tau <= 0.5: msg = f"tau must be > 0.5 for stability, got {self.tau}" raise ValueError(msg)
if self.nt <= 0: msg = f"nt must be positive, got {self.nt}" raise ValueError(msg)
valid_schemes = _valid_collision_schemes() if self.collision_scheme not in valid_schemes: msg = f"collision_scheme must be one of {sorted(valid_schemes)}, got '{self.collision_scheme}'" raise ValueError(msg)
if self.collision_scheme == "mrt" and self.k_diag is None: msg = "k_diag must be provided when using MRT collision scheme" raise ValueError(msg)
_validate_nonnegative(self.save_interval, "save_interval") _validate_nonnegative(self.skip_interval, "skip_interval")
if self.init_type == "init_from_file" and self.init_dir is None: msg = "init_dir must be provided when init_type is 'init_from_file'" raise ValueError(msg)
if self.save_fields is not None: valid_fields = {"f", "rho", "u", "force", "force_ext", "h"} invalid = set(self.save_fields) - valid_fields if invalid: msg = f"Invalid save_fields: {invalid}. Valid fields: {valid_fields}" raise ValueError(msg)
def _validate_multiphase(self) -> None: required = ("kappa", "rho_l", "rho_v", "interface_width", "eos") for name in required: if getattr(self, name) is None: msg = f"'{name}' is required for multiphase simulations" raise ValueError(msg)
_validate_positive(self.rho_l, "rho_l") _validate_positive(self.rho_v, "rho_v") if self.rho_l is not None and self.rho_v is not None and self.rho_l <= self.rho_v: msg = f"rho_l ({self.rho_l}) must be greater than rho_v ({self.rho_v})" raise ValueError(msg) _validate_positive(self.kappa, "kappa") _validate_positive(self.interface_width, "interface_width")
valid_eos = _valid_eos() if self.eos not in valid_eos: msg = f"eos must be one of {sorted(valid_eos)}, got '{self.eos}'" raise ValueError(msg)
@property def is_single_phase(self) -> bool: return self.sim_type == "single_phase"
@property def is_multiphase(self) -> bool: return self.sim_type == "multiphase"
@property def force_enabled(self) -> bool: """True if any ``*_force`` field is populated.""" return any(getattr(self, f.name) is not None for f in dataclasses.fields(self) if f.name.endswith("_force"))
# Serialisation
def to_dict(self) -> dict[str, Any]: from dataclasses import asdict
d = asdict(self) extra = d.pop("extra", {}) d.update(extra) d["simulation_type"] = self.sim_type return d
def __repr__(self) -> str: return ( f"SimulationConfig(\n" f" sim_type={self.sim_type!r},\n" f" grid_shape={self.grid_shape!r},\n" f" lattice_type={self.lattice_type!r},\n" f" tau={self.tau!r},\n" f" nt={self.nt!r},\n" f" collision_scheme={self.collision_scheme!r},\n" f" init_type={self.init_type!r},\n" f")" )
def get_array_eligible_fields() -> frozenset[str]: return frozenset(f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(ARRAY_ELIGIBLE, False))
def get_nested_sweepable_fields() -> frozenset[str]: """Return field names whose dict sub-keys may carry list sweep values.""" return frozenset(f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(NESTED_SWEEPABLE, False))
def get_fields_for_section(section: str) -> frozenset[str]: return frozenset( f.name for f in dataclasses.fields(SimulationConfig) if f.metadata.get(CONFIG_SECTION, "simulation_type") == section )

"""Tests for the plotting operator package and figure builder."""
from __future__ import annotations import numpy as np import pytest from tud_lbm.config import SimulationConfig from tud_lbm.io.plotting.figure_builder import FigureBuilder from tud_lbm.registry import get_operator_names
@pytest.fixture def plotting_run_dir(tmp_path): run_dir = tmp_path / "run" data_dir = run_dir / "data" data_dir.mkdir(parents=True) return run_dir
@pytest.fixture def simple_config(): return SimulationConfig( plot_fields=["density", "velocity"], simulation_name="test", )
def test_layout_1(): assert FigureBuilder._layout(1) == (1, 1)
def test_layout_4(): assert FigureBuilder._layout(4) == (2, 2)
def test_layout_5(): ncols, nrows = FigureBuilder._layout(5) assert ncols * nrows >= 5
def test_build_calls_savefig(plotting_run_dir, simple_config): builder = FigureBuilder(simple_config, plotting_run_dir) data = { "rho": np.ones((16, 16, 1, 1, 1)), "u": np.zeros((16, 16, 1, 1, 2)), } path = builder.build(data, timestep=100) assert path is not None assert path.exists()
def test_build_skips_unavailable_operators(plotting_run_dir): config = SimulationConfig(plot_fields=["density", "force"]) builder = FigureBuilder(config, plotting_run_dir) data = {"rho": np.ones((8, 8, 1, 1, 1))} path = builder.build(data, timestep=5) assert path is not None assert path.exists()
def test_unknown_plotfield_warns(plotting_run_dir): config = SimulationConfig(plot_fields=["nonexistent"]) with pytest.warns(UserWarning, match="No plot operator registered"): FigureBuilder(config, plotting_run_dir)
def test_density_operator_registered(): assert "density" in get_operator_names("plotting")
def test_velocity_operator_registered(): names = get_operator_names("plotting") assert "velocity" in names
def test_analysis_operators_registered(): names = get_operator_names("analysis") assert "max_velocity" in names assert "density_ratio" in names assert "avg_density" in names assert "simulation_csv" in names
def test_build_all_creates_one_figure_per_snapshot(plotting_run_dir, simple_config): np.savez( plotting_run_dir / "data" / "timestep_10.npz", rho=np.ones((6, 6, 1, 1, 1)), u=np.zeros((6, 6, 1, 1, 2)), ) np.savez( plotting_run_dir / "data" / "timestep_20.npz", rho=np.ones((6, 6, 1, 1, 1)), u=np.zeros((6, 6, 1, 1, 2)), )
builder = FigureBuilder(simple_config, plotting_run_dir) saved = builder.build_all() assert len(saved) == 2 assert all(path.exists() for path in saved)
def test_build_analysis_writes_analysis_plots(plotting_run_dir): np.savez( plotting_run_dir / "data" / "timestep_10.npz", rho=np.ones((6, 6, 1, 1, 1)), u=np.zeros((6, 6, 1, 1, 2)), ca_left=np.array(80.0), ca_right=np.array(100.0), cll_left=np.array(2.0), cll_right=np.array(5.0), ) np.savez( plotting_run_dir / "data" / "timestep_20.npz", rho=np.ones((6, 6, 1, 1, 1)) * 2, u=np.ones((6, 6, 1, 1, 2)) * 0.1, ca_left=np.array(81.0), ca_right=np.array(99.0), cll_left=np.array(2.5), cll_right=np.array(5.4), )
config = SimulationConfig(plot_fields=["max_velocity", "avg_density", "contact_angles_pair"]) builder = FigureBuilder(config, plotting_run_dir) written = builder.build_analysis() assert len(written) == 3 assert all(path.exists() for path in written)
def test_build_all_accepts_run_directory(plotting_run_dir: str): np.savez( plotting_run_dir / "data" / "timestep_1.npz", rho=np.ones((6, 6, 1, 1, 1)), u=np.zeros((6, 6, 1, 1, 2)), ) config = SimulationConfig(simulation_name="demo", plot_fields=["density", "velocity"]) builder = FigureBuilder(config=config, run_dir=str(plotting_run_dir))
saved = builder.build_all()
assert len(saved) == 1 assert saved[0].exists()
plots = list((plotting_run_dir / "plots").glob("*.png")) assert len(plots) == 1

